import{_ as e,o as a,c as l,a4 as r}from"./chunks/framework.2-Vke5-n.js";const m=JSON.parse('{"title":"","description":"","frontmatter":{"sidebarDepth":4,"author":"フューチャー株式会社","layout":"home","hero":{"name":"DB設計ガイドライン","tagline":"Database Design Guidelines","actions":[{"theme":"brand","text":"PostgreSQL設計ガイドライン","link":"./postgresql_guidelines.md"},{"theme":"brand","text":"DynamoDB設計ガイドライン","link":"./dynamodb_guidelines.md"}]}},"headers":[],"relativePath":"documents/forDB/index.md","filePath":"documents/forDB/index.md"}'),i={name:"documents/forDB/index.md"};function o(n,t,s,d,h,u){return a(),l("div",null,[...t[0]||(t[0]=[r('<h2 id="はじめに" tabindex="-1">はじめに <a class="header-anchor" href="#はじめに" aria-label="Permalink to &quot;はじめに&quot;">​</a></h2><p>DB設計に関するガイドラインとして、PostgreSQL設計ガイドラインとDynamoDB設計ガイドラインの2本を提供する。各文書の位置づけと前提は本ページの各セクションを参照。</p><div class="warning custom-block"><p class="custom-block-title">免責事項</p><ul><li>有志で作成したドキュメントである。フューチャーには多様なプロジェクトが存在し、それぞれの状況に合わせて工夫された開発プロセスや高度な開発支援環境が存在する。本ガイドラインはフューチャーの全ての部署／プロジェクトで適用されているわけではなく、有志が観点を持ち寄って新たに整理したものである</li><li>相容れない部分があればその領域を書き換えて利用することを想定している。プロジェクト固有の背景や要件への配慮は、ガイドライン利用者が最終的に判断すること。本ガイドラインに必ず従うことは求めておらず、設計案の提示と、それらの評価観点を利用者に提供することを主目的としている</li><li>掲載内容および利用に際して発生した問題、それに伴う損害については、フューチャー株式会社は一切の責務を負わないものとする。掲載している情報は予告なく変更する場合がある</li></ul></div><h2 id="postgresql設計ガイドライン" tabindex="-1">PostgreSQL設計ガイドライン <a class="header-anchor" href="#postgresql設計ガイドライン" aria-label="Permalink to &quot;PostgreSQL設計ガイドライン&quot;">​</a></h2><p>本ガイドラインはPostgreSQLを使用する開発者向けに、DBのテーブルやカラムの命名・型桁・制約などのスキーマ管理に加え、履歴・排他制御・マルチテナント対応などアプリケーション設計を含む内容についての設計標準を紹介する。これによりDB設計の主な論点／設計項目／設計観点を提供することで、開発者の考慮漏れを防ぐとともに、チームでの設計上の合意形成を手助けし、システム開発における標準ラインとなる設計手法を提供することでナレッジやツールの横展開を容易にすることを目指す。</p><h3 id="前提条件" tabindex="-1">前提条件 <a class="header-anchor" href="#前提条件" aria-label="Permalink to &quot;前提条件&quot;">​</a></h3><p>作成にあたって以下の想定を持つ。</p><ul><li>利用データベース：PostgreSQL</li><li>ワークロード： OLTP（オンライントランザクション処理）の業務システム開発</li><li>主にクラウド上のマネージドサービスの利用（Amazon Auroraを利用など）</li></ul><h2 id="dynamodb設計ガイドライン" tabindex="-1">DynamoDB設計ガイドライン <a class="header-anchor" href="#dynamodb設計ガイドライン" aria-label="Permalink to &quot;DynamoDB設計ガイドライン&quot;">​</a></h2><p>AWS が提供するフルマネージドな NoSQLデータベースサービスである、DynamoDBの技術選定・命名・データモデリング・パーティショニング・性能・費用・監視・運用・セキュリティなどの考慮すべき設計事項と推奨案をまとめる。</p><h3 id="適用範囲" tabindex="-1">適用範囲 <a class="header-anchor" href="#適用範囲" aria-label="Permalink to &quot;適用範囲&quot;">​</a></h3><p>DynamoDB を利用してシステムを構築する全てのエンジニアおよびアーキテクトを対象とする。業務システムの開発を想定しており、開発スピードの優先度が高いPoCや、学習目的の趣味の開発は除く。数名以上の開発チームがあり、運用保守まで見据え、安定して動作することが求められるとする。</p><p>対象外となる事項は以下の通り。</p><ul><li>DynamoDB の詳細なAPIリファレンスや具体的なコーディング実装例を網羅するものではない。それらについては、AWS公式ドキュメントや各プログラミング言語のSDKドキュメントを参照すること</li><li>DynamoDBをセッションストレージのような、限定的な用途で使うようなケース。本ガイドラインの内容は要件に対して過剰な設計になる可能性がある</li><li>特定のビジネス領域やアプリケーション固有の要件に特化した設計判断については、本ガイドラインの原則を踏まえつつ、各プロジェクトで個別検討すること</li><li>DynamoDBを利用する前提として、AWSそのものの命名や設計が必要になる。<a href="https://future-architect.github.io/coding-standards/documents/forAWSResource/AWS%E3%82%A4%E3%83%B3%E3%83%95%E3%83%A9%E3%83%AA%E3%82%BD%E3%83%BC%E3%82%B9%E5%91%BD%E5%90%8D%E8%A6%8F%E7%B4%84.html" target="_blank" rel="noreferrer">AWSインフラ命名規約</a> や<a href="/arch-guidelines/documents/forAWS/aws_guidelines.html">AWS設計ガイドライン</a> を参考にすること</li><li>インフラ構築はTerraformなどのプロビジョニングツールの利用を推奨する。<a href="/arch-guidelines/documents/forTerraform/terraform_guidelines.html">Terraform設計ガイドライン</a> を参考にすること</li></ul><h3 id="用語" tabindex="-1">用語 <a class="header-anchor" href="#用語" aria-label="Permalink to &quot;用語&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">用語</th><th style="text-align:left;">説明</th></tr></thead><tbody><tr><td style="text-align:left;">読み込みキャパシティユニット（RCU）</td><td style="text-align:left;">1秒あたりに読み込み可能なデータ量の単位</td></tr><tr><td style="text-align:left;">書き込みキャパシティユニット（WCU）</td><td style="text-align:left;">1秒あたりに書き込み可能なデータ量の単位</td></tr><tr><td style="text-align:left;">カバードクエリ</td><td style="text-align:left;">クエリ対象のすべての属性がインデックスに射影（プロジェクション）されており、テーブル本体への読み込み無しで結果を返せるクエリ</td></tr><tr><td style="text-align:left;">TTL (Time To Live)</td><td style="text-align:left;">アイテムに有効期限のタイムスタンプを設定し、期限が切れたアイテムを自動的にテーブルから削除する機能</td></tr><tr><td style="text-align:left;">未処理のアイテム (UnprocessedItems)</td><td style="text-align:left;">BatchGetItemやBatchWriteItemなどのバッチ処理で、プロビジョニングされたスループットの不足などにより、処理しきれなかったアイテム</td></tr><tr><td style="text-align:left;">条件付き書き込み (Conditional Writes)</td><td style="text-align:left;">特定の条件が満たされた場合にのみ書き込みを操作する仕組み</td></tr><tr><td style="text-align:left;">冪等性</td><td style="text-align:left;">同じ処理を複数回実行しても、結果が常に同じになる性質</td></tr><tr><td style="text-align:left;">DLQ (デッドレターキュー)</td><td style="text-align:left;">処理に失敗したメッセージやイベントを隔離するためのキュー</td></tr></tbody></table><h2 id="謝辞" tabindex="-1">謝辞 <a class="header-anchor" href="#謝辞" aria-label="Permalink to &quot;謝辞&quot;">​</a></h2><p>このアーキテクチャガイドラインの作成には多くの方々にご協力いただいた。心より感謝申し上げる。</p><p>PostgreSQL設計ガイドライン:</p><ul><li><strong>作成者</strong>: 真野隼記、武田大輝、宮崎将太、澁川喜規、村田靖拓、岸本卓也、関根直弥、清水雄一郎</li><li><strong>レビュアー</strong>: 杉江伸祐、二村暢之、佐々木伸悟、辻大志郎、尾崎駿</li></ul><p>DynamoDB設計ガイドライン:</p><ul><li><strong>作成者</strong>: 真野隼記、後藤玲雄、武田大輝、村田靖拓、村瀬善則、宮崎将太、市川燿、山本竜玄、澁川喜規</li><li><strong>レビュアー</strong>: 八木雅斗、大江聖太郎</li></ul><h2 id="articles" tabindex="-1">Articles <a class="header-anchor" href="#articles" aria-label="Permalink to &quot;Articles&quot;">​</a></h2><ul><li>2025.05.30 <a href="https://future-architect.github.io/articles/20250530a/" target="_blank" rel="noreferrer">PostgreSQL設計ガイドラインのご紹介</a></li><li>2026.02.27 <a href="https://future-architect.github.io/articles/20260227a/" target="_blank" rel="noreferrer">DynamoDB設計ガイドラインを公開しました</a></li></ul><div class="next-page-nav"><p>次のページ: <a href="./postgresql_guidelines.html">PostgreSQL設計ガイドライン</a>・<a href="./dynamodb_guidelines.html">DynamoDB設計ガイドライン</a></p></div>',25)])])}const g=e(i,[["render",o]]);export{m as __pageData,g as default};
